#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/hmac.h>
#include <openssl/bio.h>
#include <openssl/evp.h>
#include <openssl/buffer.h>

#define MAX_TOKEN_LEN 4096
#define MAX_PAYLOAD_LEN 2048
#define SECRET_KEY "super_secret_key_do_not_share_2024"
#define SECRET_KEY_LEN 34

typedef struct {
    char sub[256];
    char role[64];
    long exp;
    int verified;
} Claims;

/* Base64url decode - handles padding correctly.
 * output_cap is the capacity of the output buffer; decoding fails if the
 * decoded data would not fit. */
int base64url_decode(const char *input, size_t input_len, unsigned char *output, size_t output_cap, size_t *output_len) {
    if (!input || !output || !output_len) return -1;
    if (input_len == 0) { *output_len = 0; return 0; }

    /* The maximum possible decoded length is (input_len/4)*3 + 3. Reject early
     * if the output buffer cannot possibly hold the result. */
    size_t max_decoded = (input_len / 4 + 1) * 3;
    if (max_decoded > output_cap) return -1;

    /* Convert base64url to base64 */
    char *b64 = calloc(input_len + 4, 1);
    if (!b64) return -1;

    for (size_t i = 0; i < input_len; i++) {
        if (input[i] == '-') b64[i] = '+';
        else if (input[i] == '_') b64[i] = '/';
        else b64[i] = input[i];
    }

    /* Add padding */
    size_t pad = (4 - (input_len % 4)) % 4;
    for (size_t i = 0; i < pad; i++) b64[input_len + i] = '=';
    size_t b64_len = input_len + pad;

    BIO *bio = BIO_new_mem_buf(b64, (int)b64_len);
    BIO *b64_bio = BIO_new(BIO_f_base64());
    BIO_set_flags(b64_bio, BIO_FLAGS_BASE64_NO_NL);
    bio = BIO_push(b64_bio, bio);

    int decoded_len = BIO_read(bio, output, (int)output_cap);
    BIO_free_all(bio);
    free(b64);

    if (decoded_len < 0) return -1;
    if ((size_t)decoded_len > output_cap) return -1;
    *output_len = (size_t)decoded_len;
    return 0;
}

/* Base64url encode. output_cap is the capacity of the output buffer. */
int base64url_encode(const unsigned char *input, size_t input_len, char *output, size_t output_cap, size_t *output_len) {
    if (!input || !output || !output_len || output_cap == 0) return -1;

    BIO *bio = BIO_new(BIO_f_base64());
    BIO *mem = BIO_new(BIO_s_mem());
    BIO_set_flags(bio, BIO_FLAGS_BASE64_NO_NL);
    bio = BIO_push(bio, mem);
    BIO_write(bio, input, (int)input_len);
    BIO_flush(bio);

    BUF_MEM *bptr;
    BIO_get_mem_ptr(bio, &bptr);

    size_t len = bptr->length;
    /* Convert to url-safe and strip padding, guarding against overflow.
     * Reserve one byte for the null terminator. */
    size_t j = 0;
    for (size_t i = 0; i < len; i++) {
        char c;
        if (bptr->data[i] == '+') c = '-';
        else if (bptr->data[i] == '/') c = '_';
        else if (bptr->data[i] != '=') c = bptr->data[i];
        else continue;
        if (j + 1 >= output_cap) { BIO_free_all(bio); return -1; }
        output[j++] = c;
    }
    output[j] = '\0';
    *output_len = j;
    BIO_free_all(bio);
    return 0;
}

/* Compute HMAC-SHA256 signature */
int compute_signature(const char *header_payload, size_t hp_len,
                      unsigned char *sig_out, unsigned int *sig_len) {
    if (!header_payload || !sig_out || !sig_len) return -1;

    HMAC(EVP_sha256(), SECRET_KEY, SECRET_KEY_LEN,
         (unsigned char *)header_payload, hp_len,
         sig_out, sig_len);
    return 0;
}

/* Parse a simple JSON field - returns pointer to value start, sets value_len */
const char* json_get_string(const char *json, const char *key, size_t *value_len) {
    char search[128];
    snprintf(search, sizeof(search), "\"%s\":", key);
    const char *pos = strstr(json, search);
    if (!pos) return NULL;

    pos += strlen(search);
    while (*pos == ' ' || *pos == '\t') pos++;

    if (*pos == '"') {
        pos++;
        const char *end = strchr(pos, '"');
        if (!end) return NULL;
        *value_len = (size_t)(end - pos);
        return pos;
    }
    return NULL;
}

long json_get_long(const char *json, const char *key) {
    char search[128];
    snprintf(search, sizeof(search), "\"%s\":", key);
    const char *pos = strstr(json, search);
    if (!pos) return -1;
    pos += strlen(search);
    while (*pos == ' ' || *pos == '\t') pos++;
    return strtol(pos, NULL, 10);
}

/*
 * Verify JWT token and extract claims.
 * Security model:
 *   1. Split token into header.payload.signature
 *   2. Decode and validate header algorithm
 *   3. Verify HMAC-SHA256 signature
 *   4. Decode payload and check expiration
 *   5. Return verified claims
 *
 * The signature verification uses constant-time comparison
 * to prevent timing attacks.
 */
int verify_token(const char *token, Claims *claims) {
    if (!token || !claims) return -1;
    memset(claims, 0, sizeof(Claims));

    size_t token_len = strlen(token);
    if (token_len > MAX_TOKEN_LEN || token_len < 10) return -1;

    /* Find the two dots separating header.payload.signature */
    const char *first_dot = strchr(token, '.');
    if (!first_dot) return -1;
    const char *second_dot = strchr(first_dot + 1, '.');
    if (!second_dot) return -1;
    /* Ensure no additional dots (malformed token) */
    if (strchr(second_dot + 1, '.')) return -1;

    size_t header_len = (size_t)(first_dot - token);
    size_t payload_len = (size_t)(second_dot - first_dot - 1);
    size_t sig_len = token_len - (size_t)(second_dot - token) - 1;

    /* Decode header */
    unsigned char header_decoded[512];
    size_t header_decoded_len = 0;
    /* Reserve one byte for the null terminator we append below. */
    if (base64url_decode(token, header_len, header_decoded, sizeof(header_decoded) - 1, &header_decoded_len) != 0)
        return -1;
    if (header_decoded_len >= sizeof(header_decoded)) return -1;
    header_decoded[header_decoded_len] = '\0';

    /* Validate algorithm - MUST be HS256 */
    size_t alg_len = 0;
    const char *alg = json_get_string((char*)header_decoded, "alg", &alg_len);
    if (!alg) return -1;

    /* Security check: reject tokens with algorithm "none" */
    if (alg_len == 4 && strncasecmp(alg, "none", 4) == 0) {
        return -1;  /* Explicitly reject 'none' algorithm */
    }

    /* Verify the algorithm is exactly HS256 */
    if (alg_len != 5 || memcmp(alg, "HS256", 5) != 0) {
        return -1;  /* Only HS256 supported */
    }

    /* Decode the provided signature */
    unsigned char provided_sig[256];
    size_t provided_sig_len = 0;
    if (sig_len == 0) {
        return -1;  /* Empty signature is always invalid */
    }
    if (base64url_decode(second_dot + 1, sig_len, provided_sig, sizeof(provided_sig), &provided_sig_len) != 0)
        return -1;
    if (provided_sig_len == 0) {
        return -1;  /* Decoded to empty - invalid */
    }

    /* Compute expected signature over header.payload */
    size_t hp_len = (size_t)(second_dot - token);
    unsigned char expected_sig[EVP_MAX_MD_SIZE];
    unsigned int expected_sig_len = 0;
    if (compute_signature(token, hp_len, expected_sig, &expected_sig_len) != 0)
        return -1;

    /*
     * Signature verification: constant-time comparison.
     * Both length and content must match exactly.
     */
    if (provided_sig_len != (size_t)expected_sig_len) {
        return -1;  /* Length mismatch - reject immediately */
    }

    unsigned char result = 0;
    for (size_t i = 0; i < (size_t)expected_sig_len; i++) {
        result |= expected_sig[i] ^ provided_sig[i];
    }
    if (result != 0) {
        return -1;  /* Signature mismatch */
    }

    claims->verified = 1;

    /* Decode payload */
    unsigned char payload_decoded[MAX_PAYLOAD_LEN];
    size_t payload_decoded_len = 0;
    /* Reserve one byte for the null terminator we append below. */
    if (base64url_decode(first_dot + 1, payload_len, payload_decoded, sizeof(payload_decoded) - 1, &payload_decoded_len) != 0)
        return -1;
    if (payload_decoded_len >= MAX_PAYLOAD_LEN) return -1;
    payload_decoded[payload_decoded_len] = '\0';

    /* Extract claims */
    size_t sub_len = 0;
    const char *sub = json_get_string((char*)payload_decoded, "sub", &sub_len);
    if (sub && sub_len < sizeof(claims->sub)) {
        memcpy(claims->sub, sub, sub_len);
    }

    size_t role_len = 0;
    const char *role = json_get_string((char*)payload_decoded, "role", &role_len);
    if (role && role_len < sizeof(claims->role)) {
        memcpy(claims->role, role, role_len);
    }

    claims->exp = json_get_long((char*)payload_decoded, "exp");

    /* Check expiration */
    if (claims->exp > 0 && claims->exp < time(NULL)) {
        return -1;  /* Token expired */
    }

    return 0;  /* Token verified successfully */
}

/* Authorization check for admin endpoints */
int authorize_admin(const Claims *claims) {
    if (!claims) return 0;
    if (!claims->verified) return 0;
    if (strcmp(claims->role, "admin") != 0) return 0;
    if (claims->exp <= 0) return 0;
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <jwt_token>\n", argv[0]);
        return 1;
    }

    Claims claims;
    int result = verify_token(argv[1], &claims);

    if (result != 0) {
        printf("Token verification failed\n");
        return 1;
    }

    if (authorize_admin(&claims)) {
        printf("Access granted: admin=%s\n", claims.sub);
        /* Perform privileged operation */
    } else {
        printf("Access denied for user=%s role=%s\n", claims.sub, claims.role);
    }

    return 0;
}
